/* Google Flights search via the server-side SerpApi gateway. */
(() => {
  document.head.insertAdjacentHTML('beforeend','<style>.airline-brand{display:flex;align-items:center;gap:11px}.airline-brand img{width:42px;height:42px;object-fit:contain;border:1px solid #e2e8f0;border-radius:10px;padding:5px;background:#fff}.airline-brand span{display:grid;gap:3px}.return-selection-note,.journey-selected{margin:0 0 16px;padding:13px 15px;border:1px solid #bfdbfe;border-radius:10px;background:#eff6ff;color:#173d82;font-weight:700}.journey-selected small{display:block;margin-top:5px;color:#526b8e;font-weight:500}.result-price b:after{content:"Harga per orang";display:block;margin-top:4px;color:#526b8e;font-size:.72rem;font-weight:600}.flight-result-rich{grid-template-columns:minmax(150px,.9fr) minmax(205px,1.15fr) minmax(100px,.45fr) auto!important;gap:18px!important;padding:22px!important;border-radius:12px!important;box-shadow:0 8px 22px rgba(15,23,42,.05);transition:.2s}.flight-result-rich:hover{box-shadow:0 14px 28px rgba(15,23,42,.1);transform:translateY(-1px)}.flight-result-rich .result-price button{border-radius:7px;padding:9px 17px}.flight-details{grid-column:1/-1;margin:0!important;padding:17px 0 0!important}.itinerary-timeline{display:grid;gap:12px;margin:0;padding:0;list-style:none}.itinerary-leg{position:relative;padding:0 0 13px 22px;border-left:2px solid #bfdbfe}.itinerary-leg:last-child{padding-bottom:0;border-left-color:transparent}.itinerary-leg:before{content:"";position:absolute;left:-6px;top:3px;width:10px;height:10px;border-radius:50%;background:#1e3a8a;border:2px solid #dbeafe}.itinerary-leg strong{display:block;color:#172033}.itinerary-leg span,.itinerary-leg em{display:block;margin-top:4px;color:#526b8e;font-size:.82rem;font-style:normal}.itinerary-leg em{padding-top:8px;color:#1e3a8a;font-weight:600}@media(max-width:760px){.flight-result-rich{grid-template-columns:1fr 1fr!important}.flight-result-rich .flight-details{grid-column:1/-1}.flight-result-rich .result-price{text-align:left}}@media(max-width:520px){.flight-result-rich{grid-template-columns:1fr!important}}</style>');
  const code=value=>String(value||'').trim().match(/^([A-Za-z]{3})$|\b([A-Za-z]{3})\b(?=\)?\s*$)/)?.slice(1).find(Boolean)?.toUpperCase()||'';
  const money=(value,currency)=>new Intl.NumberFormat('id-ID',{style:'currency',currency,maximumFractionDigits:0}).format(Number(value));
  const duration=value=>{const minutes=Number(value)||0;return minutes?`${Math.floor(minutes/60)?`${Math.floor(minutes/60)} jam `:''}${minutes%60?`${minutes%60} menit`:''}`.trim():'—'};
  const dateTime=value=>{const date=new Date(String(value||'').replace(' ','T'));return Number.isNaN(date.valueOf())?'—':new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(date)};
  const airport=value=>String(value||'').replace(/\b(Bandar Udara|Airport)\b/gi,'').replace(/\b(Internasional|International)\b/gi,'').replace(/\s+/g,' ').trim();
  const classes={1:'Ekonomi',2:'Ekonomi Premium',3:'Bisnis',4:'Kelas Utama'};
  const api=async payload=>{const response=await fetch('/api/flights/search.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,departureDate:payload.departureDate||payload.departure,returnDate:payload.returnDate??payload.return??''})}),data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Pencarian penerbangan belum tersedia.');return data};
  const returnApi=async(departureToken,currency)=>{const response=await fetch('/api/flights/return.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({departureToken,currency})}),data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Penerbangan pulang belum tersedia.');return data};
  const activeCurrency=()=>document.querySelector('#currency')?.value||localStorage.getItem('jtm-currency')||'IDR';
  const form=document.querySelector('#search-form');
  const payload=()=>{const returnDate=document.querySelector('#return-date');return {origin:code(document.querySelector('#origin')?.value),destination:code(document.querySelector('#destination')?.value),departureDate:document.querySelector('#travel-date')?.value,returnDate:returnDate?.disabled?'':returnDate?.value||'',adults:Number(document.querySelector('[data-count="adults"]')?.textContent||1),children:Number(document.querySelector('[data-count="children"]')?.textContent||0),infants:Number(document.querySelector('[data-count="infants"]')?.textContent||0),directOnly:document.querySelector('[name="direct-only"]')?.checked||false,travelClass:({'Ekonomi':1,'Ekonomi Premium':2,'Bisnis':3,'Kelas Utama / Suites':4})[document.querySelector('#booking-class')?.value]||1,currency:activeCurrency()}};
  if(form)form.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();const feedback=document.querySelector('#search-feedback'),request=payload();if(!request.origin||!request.destination||request.origin===request.destination){feedback.textContent='Pilih bandara asal dan tujuan yang berbeda dari daftar.';return}const button=form.querySelector('.primary-button');button.disabled=true;feedback.textContent='Mencari penerbangan…';try{const data=await api(request);data.labels={origin:window.JTM_AIRPORTS?.label(request.origin)||request.origin,destination:window.JTM_AIRPORTS?.label(request.destination)||request.destination};sessionStorage.setItem('jtm-flight-search',JSON.stringify(data));location.assign('/results/')}catch(error){feedback.textContent=error.message}finally{button.disabled=false}},true);
  const root=document.querySelector('#flight-results');if(!root)return;let data;try{data=JSON.parse(sessionStorage.getItem('jtm-flight-search')||'')}catch{}if(!data?.ok)return;let visible=[];
  const timeline=item=>`<ol class="itinerary-timeline">${(item.flights||[]).map((leg,index)=>`<li class="itinerary-leg"><strong>${airport(leg.departure_airport?.name)} · ${dateTime(leg.departure_airport?.time)}</strong><span>${leg.airline||''} ${leg.flight_number||''} · ${duration(leg.duration)}</span><strong>${airport(leg.arrival_airport?.name)} · ${dateTime(leg.arrival_airport?.time)}</strong>${index<item.flights.length-1&&item.layovers?.[index]?`<em>Transit ${airport(item.layovers[index].name)} · ${duration(item.layovers[index].duration)}</em>`:''}</li>`).join('')}</ol>`;
  const draw=()=>{const all=[...(data.results.best_flights||[]),...(data.results.other_flights||[])].filter(item=>Number(item.price)>0),direct=document.querySelector('#filter-direct')?.checked,desc=document.querySelector('#sort-results')?.value==='price-desc';visible=all.filter(item=>!direct||item.flights?.length===1).sort((a,b)=>desc?b.price-a.price:a.price-b.price);const returning=!!data.returnStage,labels=data.labels||{origin:data.search.origin,destination:data.search.destination},from=returning?labels.destination:labels.origin,to=returning?labels.origin:labels.destination,travel=returning?data.search.return:data.search.departure;document.querySelector('#result-route').innerHTML=`<b>${from} → ${to}</b><br><span>${returning?'Pilih penerbangan pulang Anda':`${new Intl.DateTimeFormat('id-ID',{dateStyle:'full'}).format(new Date(`${travel}T12:00:00`))}${data.search.return?` · pulang ${new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date(`${data.search.return}T12:00:00`))}`:''} · ${data.search.adults+data.search.children+data.search.infants} penumpang · ${classes[data.search.travelClass]||'Ekonomi'}`}</span>`;const selected=returning?`<div class="journey-selected">Penerbangan pergi sudah dipilih.<small>${timeline(data.outboundFlight)}</small></div>`:'';root.innerHTML=`${returning?'<p class="return-selection-note">Pilih penerbangan pulang untuk melengkapi perjalanan pergi–pulang Anda.</p>':''}${selected}${visible.map((item,index)=>{const first=item.flights?.[0]||{},last=item.flights?.at(-1)||first,stops=(item.flights?.length||1)-1,numbers=[...new Set((item.flights||[]).map(leg=>leg.flight_number).filter(Boolean))].join(' · ');return `<article class="flight-result flight-result-rich"><div class="airline-brand">${item.airline_logo?`<img src="${item.airline_logo}" alt="${first.airline||''} logo">`:''}<span><b>${first.airline||'Maskapai'}</b><small>${numbers}${numbers?' · ':''}${first.travel_class||'Economy'}</small></span></div><div><b>${dateTime(first.departure_airport?.time)}</b><small>${airport(first.departure_airport?.name)||from} → ${airport(last.arrival_airport?.name)||to} · ${duration(item.total_duration)}</small></div><div><small>${stops?`${stops} transit`:'Langsung'}</small><button class="flight-details-toggle" type="button" data-detail="${index}">Sembunyikan detail</button></div><div class="result-price"><b>${money(item.price,data.search.currency)}</b><button type="button" data-flight="${index}">${returning?'Pilih pulang':'Pilih pergi'}</button></div><div class="flight-details" id="flight-detail-${index}">${timeline(item)}</div></article>`}).join('')||'<p>Tidak ada penerbangan berharga valid untuk filter ini.</p>'}`};
  const refresh=async()=>{const currency=activeCurrency();if(currency===data.search.currency)return;root.innerHTML='<p class="form-feedback">Memperbarui harga sesuai mata uang pilihan…</p>';try{if(data.returnStage&&data.outboundFlight?.departure_token){const response=await returnApi(data.outboundFlight.departure_token,currency);data={...data,search:{...data.search,currency},results:response.results}}else{const response=await api({...data.search,currency});response.labels=data.labels;data=response}sessionStorage.setItem('jtm-flight-search',JSON.stringify(data));draw()}catch(error){root.innerHTML=`<p class="form-feedback">${error.message}</p>`}};
  document.querySelectorAll('#filter-direct,#sort-results').forEach(control=>control.addEventListener('change',draw));document.querySelector('#currency')?.addEventListener('change',refresh);root.addEventListener('click',async event=>{const detail=event.target.closest('[data-detail]');if(detail){const panel=document.querySelector(`#flight-detail-${detail.dataset.detail}`);panel.hidden=!panel.hidden;detail.textContent=panel.hidden?'Lihat detail':'Sembunyikan detail';return}const choice=event.target.closest('[data-flight]');if(!choice)return;const selected=visible[Number(choice.dataset.flight)];if(!selected)return;choice.disabled=true;try{if(data.search.return&&!data.returnStage){if(!selected.departure_token)throw new Error('Maskapai belum menyediakan pilihan penerbangan pulang untuk rute ini.');root.innerHTML='<p class="form-feedback">Memuat pilihan penerbangan pulang…</p>';const response=await returnApi(selected.departure_token,data.search.currency);data={...data,results:response.results,returnStage:true,outboundFlight:selected};sessionStorage.setItem('jtm-flight-search',JSON.stringify(data));draw()}else{sessionStorage.setItem('jtm-flight-choice',JSON.stringify({flight:data.outboundFlight||selected,returnFlight:data.returnStage?selected:null,search:data.search,labels:data.labels}));location.assign('/checkout/')}}catch(error){root.innerHTML=`<p class="form-feedback">${error.message}</p>`}finally{choice.disabled=false}});draw();window.addEventListener('jtm-airports-ready',draw);
})();
